#!/usr/bin/env bash
# Scenario "without-claude": the Feature with Claude Code's install skipped (CI doesn't
# download it). Run with:
#   devcontainer features test --project-folder features/claude-code --features claude-code --skip-autogenerated
set -e
# shellcheck disable=SC1091
source dev-container-features-test-lib
check "hook scripts installed" test -x /usr/local/share/panem/post-create.sh
check "relay installed" test -x /usr/local/share/panem/relay-conn.sh
check "code root writable" test -w /codebase
check "tmux" command -v tmux
check "jq" command -v jq
check "socat" command -v socat
# shellcheck disable=SC2016 # $HOME expands inside bash -c, on purpose
check "claude skipped" bash -c '! command -v claude && ! test -e "$HOME/.local/bin/claude"'
reportResults
